window.RP_SESSION={"id":"S-b0e06b10c969","messages":[{"id":"RP-0247907","time":"2026-08-24T14:01:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"니콜라스는 할 일을 마치고 길드 로비에 나와 앉아있었습니다. 삐딱한 자세로 손깍지를 끼고요.","characters":["P-216ccc194078"]},{"id":"RP-0247908","time":"2026-08-24T14:01:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"그런데 아픕니다. 목이.","characters":["P-216ccc194078"]},{"id":"RP-0247909","time":"2026-08-24T14:02:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-216ccc194078"]},{"id":"RP-0247910","time":"2026-08-24T14:02:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"이건 분명히 먼지가 꽤 쌓였다는 뜻입니다. 하여 그는 근처 벽에 기대어있던 빗자루를 가져와 바닥을 쓸기 시작했습니다. 인상 팍 쓴 채.","characters":["P-216ccc194078"]},{"id":"RP-0247911","time":"2026-08-24T14:06:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"오, 니콜라스!\"","characters":["P-c93f55c91873"]},{"id":"RP-0247912","time":"2026-08-24T14:06:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"어디선가 델타인의 목소리.","characters":["P-c93f55c91873"]},{"id":"RP-0247913","time":"2026-08-24T14:06:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"가깝지만 시야에선 보이지 않습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0247914","time":"2026-08-24T14:07:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"머지 않은 데서 델타인의 목소리를 듣고는 이리저리 고개를 돌립니다.","characters":["P-216ccc194078"]},{"id":"RP-0247915","time":"2026-08-24T14:07:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"...설마 천장에?","characters":["P-216ccc194078"]},{"id":"RP-0247916","time":"2026-08-24T14:07:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"위를 바라봅니다. 설마요.","characters":["P-216ccc194078"]},{"id":"RP-0247917","time":"2026-08-24T14:07:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"정답!","characters":["P-c93f55c91873"]},{"id":"RP-0247918","time":"2026-08-24T14:07:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"안녕?\"","characters":["P-c93f55c91873"]},{"id":"RP-0247919","time":"2026-08-24T14:07:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"?\"\n\n경악","characters":["P-216ccc194078"]},{"id":"RP-0247920","time":"2026-08-24T14:07:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"드디어 네 작고 옹졸한 던전인 도서관에서 나오기로 한 거야?\"","characters":["P-c93f55c91873"]},{"id":"RP-0247921","time":"2026-08-24T14:08:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"첫번째로, 거기서 내려와. 두번째로, 도서관을 작고 옹졸하다고 부르지 마.\"\n\n팔짱 낍니다.","characters":["P-216ccc194078"]},{"id":"RP-0247922","time":"2026-08-24T14:13:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그래? 아, 나 이거 배웠어.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247923","time":"2026-08-24T14:13:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"실제로 작고 옹졸해도 그대로 말하면 기분이 나쁠 수도 있다며?\"","characters":["P-c93f55c91873"]},{"id":"RP-0247924","time":"2026-08-24T14:14:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인이 스르륵 천장에서 내려왔습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0247925","time":"2026-08-24T14:14:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"배웠는데 왜 그랬냐?\"","characters":["P-216ccc194078"]},{"id":"RP-0247926","time":"2026-08-24T14:14:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"너도 그럴 줄 몰랐지. 넌 책 많이 읽잖아.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247927","time":"2026-08-24T14:15:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그럼 실제로 도서관이 좀 작은 것도 받아들일 수 있을 줄 알았거든.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247928","time":"2026-08-24T14:16:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"도서관의 가치는 넓이로 정해지는 게 아니거든.\"","characters":["P-216ccc194078"]},{"id":"RP-0247929","time":"2026-08-24T14:20:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"오, 나 그 말 알아.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247930","time":"2026-08-24T14:20:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어떤 책이 꽂혀 있냐가 더 중요하다.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247931","time":"2026-08-24T14:20:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이거 맞지?\"","characters":["P-c93f55c91873"]},{"id":"RP-0247932","time":"2026-08-24T14:21:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"정확해.\"","characters":["P-216ccc194078"]},{"id":"RP-0247933","time":"2026-08-24T14:21:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"그러니까 아는데 왜 그랬냐고?!\"","characters":["P-216ccc194078"]},{"id":"RP-0247934","time":"2026-08-24T14:21:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"작은 건 사실이잖아.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247935","time":"2026-08-24T14:21:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그 말대로 작다고 가치 없는 건 아니니까.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247936","time":"2026-08-24T14:23:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그래서 그걸 아는 너는 작다고 해도 기분 나빠하지 않을 줄 알았지!\"","characters":["P-c93f55c91873"]},{"id":"RP-0247937","time":"2026-08-24T14:23:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"골똘. 타당한 말이긴 하네요.\n\n\"애초에 도서관의 넓이보다 꽂혀있는 책이 중요하다는 말이 왜 생겼다고 생각해?\"","characters":["P-216ccc194078"]},{"id":"RP-0247938","time":"2026-08-24T14:24:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"그건 도서관의 넓이에 집착하는 머저리들이 많기 때문이라고.\"","characters":["P-216ccc194078"]},{"id":"RP-0247939","time":"2026-08-24T14:24:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"잠깐, 그게 너야?\"","characters":["P-c93f55c91873"]},{"id":"RP-0247940","time":"2026-08-24T14:24:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"난 네가 그러지 않을 줄 알았는데.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247941","time":"2026-08-24T14:25:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"아니아니, 난 오히려 네가 그런 부류라고 생각해서 이렇게 된거잖아.\"","characters":["P-216ccc194078"]},{"id":"RP-0247942","time":"2026-08-24T14:26:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"왜 그랬대?\"","characters":["P-c93f55c91873"]},{"id":"RP-0247943","time":"2026-08-24T14:26:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아무튼 간에 밖으로 나온 거 엄청 오랜만이지?\"","characters":["P-c93f55c91873"]},{"id":"RP-0247944","time":"2026-08-24T14:26:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"자, 햇빛도 좀 보고 그래. 바로 이게 태양이란 거야.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247945","time":"2026-08-24T14:26:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인이 커튼을 착 걷었습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0247946","time":"2026-08-24T14:27:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"화들짝 놀라면서 움츠러듭니다.\n\n\"으아아 내 눈.\"","characters":["P-216ccc194078"]},{"id":"RP-0247947","time":"2026-08-24T14:28:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"험, 오늘 햇빛이 그정돈 아닌데.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247948","time":"2026-08-24T14:30:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"소매로 눈 위를 가려 그늘을 만듭니다.\n\n\"닫아, 빨리. 너무 오랜만에 봐서 그래.\"","characters":["P-216ccc194078"]},{"id":"RP-0247949","time":"2026-08-24T14:32:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"킁킁킁킁...\n\n책 냄새를 맡으며 이리저리 돌아다니는 쥐... 라기엔 너무 큰 존재 한 마리.\n\n\"책 냄새는 참 향긋하단 말이지.\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247952","time":"2026-08-24T14:33:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"책읽음햄찌.","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247953","time":"2026-08-24T14:35:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"아니... 이럴때가 아니다. 무기고와 훈련실을 보면 이 길드의 수준을 알 수 있을 터!!\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247954","time":"2026-08-24T14:36:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"발발거리며 도서관을 나섭니다.","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247955","time":"2026-08-24T14:37:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"발소리에 고개를 돌렸다가 도서관 입구에서 걸어나오는 햄 찌와 눈이 마주칩니다.","characters":["P-216ccc194078"]},{"id":"RP-0247956","time":"2026-08-24T14:37:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"오, 쥐 데미간이네?\"","characters":["P-c93f55c91873"]},{"id":"RP-0247957","time":"2026-08-24T14:38:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"햄스터 데미간이겠지.\"","characters":["P-216ccc194078"]},{"id":"RP-0247958","time":"2026-08-24T14:39:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"반가워 친구들, 이번에 새로 들어온 햄 주니어라고 해! 햄 찌라고 불러도 되고 말야.\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247959","time":"2026-08-24T14:43:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"험 씨군요. 길드 소개해드릴까요?","characters":["P-c93f55c91873"]},{"id":"RP-0247960","time":"2026-08-24T14:43:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"그래, 햄.\"\n\n떨떠름..\n\n\"플린트라고 불러.\"","characters":["P-216ccc194078"]},{"id":"RP-0247961","time":"2026-08-24T14:46:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"플린트? 내 권총이 플린트 락 인데!!\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247962","time":"2026-08-24T14:46:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"신나서 권총을 꺼냅니다.","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247963","time":"2026-08-24T14:47:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"얘 성이 특이하긴 하죠?\"","characters":["P-c93f55c91873"]},{"id":"RP-0247964","time":"2026-08-24T14:49:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"델타인을 흘겨보고는 총으로 눈을 돌립니다.\n\n\"길드에 총 다를 줄 아는 사람이 몇 없던데.\"","characters":["P-216ccc194078"]},{"id":"RP-0247965","time":"2026-08-24T14:50:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"근데 총이 은근 다루기가 쉽다던데?\"","characters":["P-c93f55c91873"]},{"id":"RP-0247966","time":"2026-08-24T14:50:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"비싼 게 문제래.","characters":["P-c93f55c91873"]},{"id":"RP-0247967","time":"2026-08-24T14:51:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"그렇찍. 장전이 문제고 쏘는건... 쉬웡.\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247968","time":"2026-08-24T14:51:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"얘한테 쏴봐.\"","characters":["P-216ccc194078"]},{"id":"RP-0247969","time":"2026-08-24T14:51:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"...농담이야.\"","characters":["P-216ccc194078"]},{"id":"RP-0247973","time":"2026-08-24T14:55:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"동료를 쏠 수는 없찍.\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247974","time":"2026-08-24T14:55:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"그나저나, 여기 무기고나 훈련장이 어디 있는지 알려줄 수 있찍?\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247975","time":"2026-08-24T14:56:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"나가서 왼쪽. 캠프장 지나서.\"","characters":["P-216ccc194078"]},{"id":"RP-0247976","time":"2026-08-24T14:58:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이리 오세요. 안내해드릴게요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247977","time":"2026-08-24T14:58:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"너도 와, 니콜라스!\"","characters":["P-c93f55c91873"]},{"id":"RP-0247978","time":"2026-08-24T14:58:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"다시 깊고 어두운 도서관으로 들어가지 말고!\"","characters":["P-c93f55c91873"]},{"id":"RP-0247979","time":"2026-08-24T14:58:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"고맙찍.\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247980","time":"2026-08-24T14:58:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"\"내키지는 않지만.\"\n\n따라가겠다는 뜻.","characters":["P-216ccc194078"]},{"id":"RP-0247981","time":"2026-08-24T14:59:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"발발발 따라갑니다.","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247982","time":"2026-08-24T15:00:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"드디어 밖으로 기어나온 니진.","characters":["P-c93f55c91873"]},{"id":"RP-0247983","time":"2026-08-24T15:04:00+09:00","room":"RP","name":"니콜라스 플린트","profile":"니콜라스 플린트","identity":"reviewed","type":"dialogue","body":"기껏 나와놓고는 그런 사람 같지 않게 터덜터덜 걷습니다.","characters":["P-216ccc194078"]},{"id":"RP-0247984","time":"2026-08-24T15:06:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"여기가 훈련장이에요. 생각보다 넓죠?\"","characters":["P-c93f55c91873"]},{"id":"RP-0247985","time":"2026-08-24T15:09:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"허수아비를 망가뜨리면 안되니까, 따로 표적을 구하는 게 좋을지도 모르겠네요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247986","time":"2026-08-24T15:11:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"오, 넓구만.\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247987","time":"2026-08-24T15:24:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그리고 저기가 빨래터, 저기가 숲.\"","characters":["P-c93f55c91873"]},{"id":"RP-0247988","time":"2026-08-24T15:24:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"저긴 대장간이고, 참, 청소 잘하세요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0247990","time":"2026-08-24T15:39:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"내가 청소는 좀 하지!\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247991","time":"2026-08-24T16:06:00+09:00","room":"RP","name":"햄 주니어","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-c6b8c16e2fba"]},{"id":"RP-0247992","time":"2026-08-24T21:41:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c93f55c91873"]},{"id":"RP-0247993","time":"2026-08-24T21:41:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
